<?php

declare(strict_types=1);

namespace App\Http\Controllers;

use Illuminate\Http\Response;
use Symfony\Component\HttpFoundation\BinaryFileResponse;

/**
 * Serves stable branding URLs with MIME-safe same-format fallbacks when a
 * deployment is missing one of the optimized public assets.
 */
final class BrandingAssetController extends Controller
{
    private const FALLBACK_LOGO_SVG = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" role="img" aria-label="lskyPai"><rect width="64" height="64" rx="14" fill="#075985"/><path fill="#fff" d="M18 14h9v24h21v10H18z"/></svg>';

    private const FALLBACK_ICON_PNG = '';

    private const FALLBACK_APPLE_TOUCH_ICON_PNG = '';

    private const FALLBACK_BACKGROUND_WEBP = '';

    private const FALLBACK_EMPTY_WEBP = '';

    private const FALLBACK_AVATAR_WEBP = '';

    private const THEMES = ['anime', 'technology', 'elegant'];

    private const THEME_ASSETS = ['hero', 'auth', 'empty'];

    private string $brandingRoot;

    private string $legacyFaviconPath;

    public function __construct(?string $brandingRoot = null, ?string $legacyFaviconPath = null)
    {
        $this->brandingRoot = $brandingRoot ?? public_path('branding');
        $this->legacyFaviconPath = $legacyFaviconPath ?? public_path('favicon.ico');
    }

    public function favicon(): Response|BinaryFileResponse
    {
        return $this->send('favicon.ico', 'image/x-icon', $this->fallbackIco());
    }

    public function logo(): Response|BinaryFileResponse
    {
        return $this->send('logo.svg', 'image/svg+xml', self::FALLBACK_LOGO_SVG);
    }

    public function brandMark(): Response|BinaryFileResponse
    {
        return $this->send(
            'brand-mark.png',
            'image/png',
            $this->decodeAsset(self::FALLBACK_APPLE_TOUCH_ICON_PNG),
        );
    }

    public function appleTouchIcon(): Response|BinaryFileResponse
    {
        return $this->send(
            'apple-touch-icon.png',
            'image/png',
            $this->decodeAsset(self::FALLBACK_APPLE_TOUCH_ICON_PNG),
        );
    }

    public function defaultAvatar(): Response|BinaryFileResponse
    {
        return $this->send(
            'default-avatar.webp',
            'image/webp',
            $this->decodeAsset(self::FALLBACK_AVATAR_WEBP),
        );
    }

    public function themeAsset(string $theme, string $asset): Response|BinaryFileResponse
    {
        if (! in_array($theme, self::THEMES, true) || ! in_array($asset, self::THEME_ASSETS, true)) {
            abort(404);
        }

        $fallback = $asset === 'empty'
            ? self::FALLBACK_EMPTY_WEBP
            : self::FALLBACK_BACKGROUND_WEBP;

        return $this->send(
            "themes/{$theme}/{$asset}.webp",
            'image/webp',
            $this->decodeAsset($fallback),
        );
    }

    private function send(string $asset, string $mimeType, string $fallback): Response|BinaryFileResponse
    {
        $customAsset = $this->brandingRoot . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $asset);
        if (is_file($customAsset)) {
            return response()->file($customAsset, $this->headers($mimeType, 31536000));
        }

        if ($asset === 'favicon.ico' && is_file($this->legacyFaviconPath)) {
            return response()->file($this->legacyFaviconPath, $this->headers($mimeType, 300));
        }

        return response(
            $fallback,
            200,
            $this->headers($mimeType, 300),
        );
    }

    /**
     * @return array<string, string>
     */
    private function headers(string $mimeType, int $maxAge): array
    {
        return [
            'Content-Type' => $mimeType,
            'Cache-Control' => "public, max-age={$maxAge}",
            'X-Content-Type-Options' => 'nosniff',
        ];
    }

    private function fallbackIco(): string
    {
        $png = $this->decodeAsset(self::FALLBACK_ICON_PNG);

        // ICONDIR + one ICONDIRENTRY followed by a 64x64 PNG payload.
        return pack(
            'vvvCCCCvvVV',
            0,
            1,
            1,
            64,
            64,
            0,
            0,
            1,
            32,
            strlen($png),
            22,
        ) . $png;
    }

    private function decodeAsset(string $encoded): string
    {
        $decoded = base64_decode($encoded, true);

        return $decoded === false ? '' : $decoded;
    }
}
